const VALUE_CHANGED_EVENT = 'valueChanged'
const EDITOR_CHANGED_EVENT = 'editorChanged'
export const MARKDOWN_INSERTION_REQUESTED_EVENT = 'insertionRequested'
export const MARKDOWN_FLUSH_REQUESTED_EVENT = 'flushRequested'
export const MARKDOWN_FOCUS_REQUESTED_EVENT = 'focusRequested'

type MarkdownDraftListener = () => void

export interface MarkdownInsertionRequest {
    acknowledge(): void
    markdown: string
    reject(error: unknown): void
}

/** Contract used by one mounted editor to read and update its active draft. */
export interface MarkdownDraftBinding {
    addEventListener(type: string, callback: EventListenerOrEventListenerObject | null): void
    edit(value: string): void
    getSnapshot(): string
    removeEventListener(type: string, callback: EventListenerOrEventListenerObject | null): void
    subscribeEditor(listener: MarkdownDraftListener): () => void
}

/** Service-owned Markdown value with external replacement and acknowledged insertion requests. */
export class MarkdownDraft extends EventTarget implements MarkdownDraftBinding {
    private editorSnapshot = { replacementRevision: 0 }
    private value: string

    constructor(initialValue: string) {
        super()
        this.value = initialValue
    }

    readonly getSnapshot = () => this.value

    readonly getEditorSnapshot = () => this.editorSnapshot

    readonly subscribe = (listener: MarkdownDraftListener) => {
        this.addEventListener(VALUE_CHANGED_EVENT, listener)

        return () => this.removeEventListener(VALUE_CHANGED_EVENT, listener)
    }

    readonly subscribeEditor = (listener: MarkdownDraftListener) => {
        this.addEventListener(EDITOR_CHANGED_EVENT, listener)

        return () => this.removeEventListener(EDITOR_CHANGED_EVENT, listener)
    }

    edit(value: string) {
        this.setValue(value)
    }

    replace(value: string) {
        this.setValue(value)
        this.editorSnapshot = { replacementRevision: this.editorSnapshot.replacementRevision + 1 }
        this.dispatchEvent(new Event(EDITOR_CHANGED_EVENT))
    }

    clear() {
        if (this.value.length === 0) return

        this.replace('')
    }

    /** Asks the mounted editor, if any, to commit its debounced buffer into this draft now. */
    readonly requestFlush = () => {
        this.dispatchEvent(new Event(MARKDOWN_FLUSH_REQUESTED_EVENT))
    }

    /** Asks the mounted editor, if any, to take keyboard focus. */
    readonly requestFocus = () => {
        this.dispatchEvent(new Event(MARKDOWN_FOCUS_REQUESTED_EVENT))
    }

    readonly requestInsertion = (markdown: string) => new Promise<void>((resolve, reject) => {
        let handled = false
        const request: MarkdownInsertionRequest = {
            acknowledge: () => {
                if (handled) return
                handled = true
                resolve()
            },
            markdown,
            reject: (error: unknown) => {
                if (handled) return
                handled = true
                reject(error)
            },
        }
        this.dispatchEvent(new CustomEvent<MarkdownInsertionRequest>(MARKDOWN_INSERTION_REQUESTED_EVENT, { detail: request }))
        if (!handled) request.reject(new Error('Markdown insertion requires a mounted editor'))
    })

    private setValue(value: string) {
        if (this.value === value) return

        this.value = value
        this.dispatchEvent(new Event(VALUE_CHANGED_EVENT))
    }
}

import { useEffect } from 'react'
import {
    MARKDOWN_FLUSH_REQUESTED_EVENT,
    MARKDOWN_FOCUS_REQUESTED_EVENT,
    MARKDOWN_INSERTION_REQUESTED_EVENT,
    type MarkdownDraftBinding,
    type MarkdownInsertionRequest,
} from '../../../services/markdown/markdown_draft'

/** Applies external replacements, insertion, flush, and focus requests from one Markdown draft to its mounted editor. */
export function useMarkdownDraft(
    draft: MarkdownDraftBinding | undefined,
    insertMarkdown: (markdown: string) => void,
    replaceMarkdown: (markdown: string) => void,
    flush: () => boolean,
    bindDraft: (draft: MarkdownDraftBinding | undefined) => void,
    focusEditor: () => void,
) {
    useEffect(() => {
        if (!draft) {
            bindDraft(undefined)

            return undefined
        }

        replaceMarkdown(draft.getSnapshot())
        bindDraft(draft)

        const unsubscribe = draft.subscribeEditor(() => replaceMarkdown(draft.getSnapshot()));
        return () => {
            unsubscribe();
            flush();
            bindDraft(undefined);
        };
    }, [bindDraft, draft, flush, replaceMarkdown])

    useEffect(() => {
        if (!draft) return undefined

        const handleInsertionRequest = (event: Event) => {
            const request = (event as CustomEvent<MarkdownInsertionRequest>).detail
            try {
                insertMarkdown(request.markdown)
                request.acknowledge()
            } catch (error) {
                request.reject(error)
            }
        }
        draft.addEventListener(MARKDOWN_INSERTION_REQUESTED_EVENT, handleInsertionRequest)

        return () => draft.removeEventListener(MARKDOWN_INSERTION_REQUESTED_EVENT, handleInsertionRequest)
    }, [draft, insertMarkdown])

    useEffect(() => {
        if (!draft) return undefined

        const handleFlushRequest = () => {
            flush()
        }
        draft.addEventListener(MARKDOWN_FLUSH_REQUESTED_EVENT, handleFlushRequest)

        return () => draft.removeEventListener(MARKDOWN_FLUSH_REQUESTED_EVENT, handleFlushRequest)
    }, [draft, flush])

    useEffect(() => {
        if (!draft) return undefined

        draft.addEventListener(MARKDOWN_FOCUS_REQUESTED_EVENT, focusEditor)

        return () => draft.removeEventListener(MARKDOWN_FOCUS_REQUESTED_EVENT, focusEditor)
    }, [draft, focusEditor])
}

